#!/usr/bin/env python3
"""Generate schema/mongodb/setup.mongodb.js from backend/outreach_db/mongodb_schema.py."""

from __future__ import annotations

import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
BACKEND = ROOT / "backend"
sys.path.insert(0, str(BACKEND))

from outreach_db.mongodb_schema import _index_specs  # noqa: E402

HEADER = """\
/**
 * Outreach Console — MongoDB schema setup
 * AUTO-GENERATED by scripts/generate_mongodb_setup_js.py — do not edit by hand.
 * Source of truth: backend/outreach_db/mongodb_schema.py
 *
 * Usage:
 *   mongosh "mongodb://127.0.0.1:27017/outreach_console" schema/mongodb/setup.mongodb.js
 *   — or —
 *   python scripts/apply_mongodb_schema.py
 *
 * Optional env: MONGODB_DB (default: outreach_console)
 * Rebuild stats: mongosh ... --eval "var REBUILD_STATS=true" schema/mongodb/setup.mongodb.js
 */

const dbName = typeof process !== "undefined" && process.env.MONGODB_DB
  ? process.env.MONGODB_DB
  : "outreach_console";

const db = db.getSiblingDB(dbName);

const emailPresent = { email: { $exists: true, $type: "string", $ne: "" } };

function idx(col, spec) {
  const keys = spec.keys;
  const opts = { ...spec };
  delete opts.keys;
  try {
    db.getCollection(col).createIndex(keys, opts);
    print(`  OK ${col}.${opts.name || JSON.stringify(keys)}`);
  } catch (e) {
    print(`  skip ${col}.${opts.name}: ${e.message}`);
  }
}

print(`Applying MongoDB schema to database: ${dbName}`);

"""


def py_keys_to_js(keys: list) -> str:
    parts = []
    for k, v in keys:
        if k == "text":
            parts.append(f'{json.dumps(k)}: "text"')
        else:
            parts.append(f"{json.dumps(k)}: {v}")
    return "{" + ", ".join(parts) + "}"


def py_filter_to_js(obj: dict) -> str:
    return json.dumps(obj, separators=(",", ": "))


def spec_to_js(col: str, spec: dict) -> str:
    keys_js = py_keys_to_js(spec["keys"])
    opts: dict = {}
    for key in ("unique", "sparse", "name", "default_language"):
        if key in spec:
            opts[key] = spec[key]
    if "partialFilterExpression" in spec:
        opts["partialFilterExpression"] = spec["partialFilterExpression"]
    opts_js = json.dumps(opts, separators=(",", ": ")).strip("{}")
    # Fix JSON booleans/null for JS (already valid)
    if opts_js:
        return f'idx("{col}", {{ keys: {keys_js}, {opts_js} }});'
    return f'idx("{col}", {{ keys: {keys_js} }});'


def main() -> None:
    lines = [HEADER]
    current_col = None
    for col, specs in _index_specs():
        if col != current_col:
            lines.append(f"\n// {col}")
            current_col = col
        for spec in specs:
            lines.append(spec_to_js(col, spec))

    lines.append(
        """
print("MongoDB schema applied.");

if (typeof REBUILD_STATS !== "undefined" && REBUILD_STATS) {
  const rows = db.github_users.aggregate([
    { $match: { country: { $exists: true, $ne: null, $ne: "" }, email: { $exists: true, $ne: null, $ne: "" } } },
    { $group: { _id: "$country", user_count: { $sum: 1 } } },
  ]).toArray();
  db.github_user_country_stats.deleteMany({});
  if (rows.length) {
    db.github_user_country_stats.insertMany(
      rows.map((r) => ({ country: r._id, user_count: r.user_count, updated_at: new Date() }))
    );
  }
  print(`Rebuilt github_user_country_stats: ${rows.length} countries`);
}
"""
    )

    out = ROOT / "schema" / "mongodb" / "setup.mongodb.js"
    out.write_text("\n".join(lines), encoding="utf-8")
    print(f"Wrote {out}")


if __name__ == "__main__":
    main()
